func TestLegacyEvaluationReportV1RemainsVerifiable(t *testing.T) {
	// Captured from the guarded, green offline evaluation on #42 head9452967;
	// never regenerated by this test or by the new source-registry evaluator.
	raw, e := os.ReadFile("testdata/legacy-evaluation-report.v1.json")
	if e != nil {
		t.Fatal(e)
	}
	var r Report
	if e = json.Unmarshal(raw, &r); e != nil {
		t.Fatal(e)
	}
	if r.Hash != "a35d3d08b18db3daf34c80aaed7c5ee2eb787656af267cf52e9bad8f69bfc63f" || r.Verify() != nil {
		t.Fatal("recorded legacy evaluation report no longer verifies")
	}
}

type relationshipGeneratorFunc func(context.Context, experiment.RelationshipProbeRequest) (experiment.RelationshipProbe, error)

func (f relationshipGeneratorFunc) ProbeRelationships(c context.Context, r experiment.RelationshipProbeRequest) (experiment.RelationshipProbe, error) {
	return f(c, r)
}

func alignmentFixture(t *testing.T) (Dataset, AlignmentPlan) {
	t.Helper()
	d, c := fixture(t)
	p, e := NewAlignmentPlan(d.Hash, strings.Repeat("a", 40), strings.Repeat("b", 40), strings.Repeat("c", 64), c.GeneratorArtifact, c.Seeds, fixtureNow.Add(-time.Hour))
	if e != nil {
		t.Fatal(e)
	}
	return d, p
}
func alignmentReceipt(r AlignmentReport, now time.Time) AlignmentReceipt {
	return AlignmentReceipt{"hws-alignment-receipt.v1", r.PlanHash, r.Hash, r.Plan.EvaluatorArtifact, now}
}
func resealAlignment(r *AlignmentReport) { r.Hash = ""; r.Hash, _ = Digest(*r) }

func TestAlignmentEvidenceAdequacyAndReproduction(t *testing.T) {
	d, p := alignmentFixture(t)
	calls := 0
	g := relationshipGeneratorFunc(func(ctx context.Context, r experiment.RelationshipProbeRequest) (experiment.RelationshipProbe, error) {
		calls++
		return experiment.GenerateRelationshipProbe(ctx, r)
	})
	r, receipt, e := RunAlignment(context.Background(), d, p, g, fixtureNow)
	if e != nil {
		t.Fatal(e)
	}
	if !r.SyntheticOnly || r.HumanValidity != AlignmentNotTested || r.CrossModelTransfer != AlignmentNotTested || r.RealStudy != "NOT_RUN" {
		t.Fatal("synthetic experiment invented scientific validity")
	}
	if calls != 2 || r.Verify(p, d, receipt) != nil || len(r.Findings) != 23 {
		t.Fatal("incomplete independently repeated report")
	}
	again, later, e := RunAlignment(context.Background(), d, p, g, fixtureNow.Add(time.Minute))
	if e != nil {
		t.Fatal(e)
	}
	a, _ := json.Marshal(r)
	b, _ := json.Marshal(again)
	if string(a) != string(b) || receipt.EvaluatedAt == later.EvaluatedAt {
		t.Fatal("execution time broke logical byte reproduction or was not retained")
	}
	for _, m := range r.Mechanics {
		if m.Status != AlignmentPass {
			t.Fatal("controlled mechanics failed", m)
		}
	}
	for _, f := range r.Findings {
		if f.ID == "hws19.10" {
			if f.Status != AlignmentPass {
				t.Fatal("independent engineering reproduction blocked by absent humans")
			}
			continue
		}
		if f.Status == AlignmentPass || f.Status == AlignmentFail {
			t.Fatal("synthetic mechanics became behavioral adequacy", f)
		}
		if strings.HasPrefix(f.ID, "hws20.") && f.FalsifierTriggered != "unknown" {
			t.Fatal("unobserved falsifier treated as false", f)
		}
	}
	for _, f := range r.Findings {
		if f.ID == "hws19.13" && f.Status != AlignmentNotTested {
			t.Fatal("future real-data path counted as calibration readiness")
		}
	}
	if r.Findings[2].Status != AlignmentInconclusive || r.Findings[18].Status != AlignmentInconclusive {
		t.Fatal("executed relationship/memory experiment reported as unrun")
	}
	for _, evidence := range []AlignmentEvidence{{}, {First: r.Evidence.First}} {
		partial, e := BuildAlignmentReport(p, evidence)
		if e != nil {
			t.Fatal(e)
		}
		if partial.Verify(p, d, alignmentReceipt(partial, fixtureNow)) != nil {
			t.Fatal("honest incomplete evidence rejected")
		}
		want := AlignmentNotTested
		if evidence.First != nil {
			want = AlignmentInconclusive
		}
		if partial.Findings[9].Status != want {
			t.Fatal("missing reproduction evidence produced PASS")
		}
	}
}

func TestAlignmentRejectsResealedClaimsAndBindings(t *testing.T) {
	d, p := alignmentFixture(t)
	r, receipt, e := RunAlignment(context.Background(), d, p, relationshipGeneratorFunc(experiment.GenerateRelationshipProbe), fixtureNow)
	if e != nil {
		t.Fatal(e)
	}
	raw, _ := json.Marshal(r)
	for _, name := range []string{"omitted", "duplicate", "renamed", "source_wording", "requirements", "source", "tree", "config_rule", "model", "dataset", "seed", "missing_evidence", "missing_repeat", "evidence_input", "human", "cross_model", "study", "calibration_pass", "falsifier_pass", "falsifier_false", "mechanics_pass"} {
		t.Run(name, func(t *testing.T) {
			var bad AlignmentReport
			_ = json.Unmarshal(raw, &bad)
			switch name {
			case "omitted":
				bad.Findings = bad.Findings[:22]
			case "duplicate":
				bad.Findings[0] = bad.Findings[1]
			case "renamed":
				bad.Registry[0].Name = "renamed"
			case "source_wording":
				bad.Registry[12].SourceWording = "future path exists"
			case "requirements":
				bad.Registry[2].EvidenceRequirements = nil
			case "source":
				bad.Plan.SourceRevision = strings.Repeat("d", 40)
			case "tree":
				bad.Plan.SourceTree = strings.Repeat("e", 40)
			case "config_rule":
				bad.Plan.DecisionRule = "always pass"
			case "model":
				bad.Plan.Model = "two-real-models"
			case "dataset":
				bad.Plan.DatasetHash = strings.Repeat("f", 64)
			case "seed":
				bad.Plan.Probe.Seeds[0]++
			case "missing_evidence":
				bad.Evidence = AlignmentEvidence{}
			case "missing_repeat":
				bad.Evidence.Repeat = nil
			case "evidence_input":
				bad.Evidence.First.Trials[0].InputHash = strings.Repeat("f", 64)
			case "human":
				bad.HumanValidity = AlignmentPass
				bad.SyntheticOnly = false
			case "cross_model":
				bad.CrossModelTransfer = AlignmentPass
			case "study":
				bad.RealStudy = "PASS"
			case "calibration_pass":
				bad.Findings[12].Status = AlignmentPass
			case "falsifier_pass":
				bad.Findings[15].Status = AlignmentPass
			case "falsifier_false":
				bad.Findings[15].FalsifierTriggered = "false"
			case "mechanics_pass":
				bad.Mechanics[0].Explanation = "human realism established"
			}
			// Attackers may recalculate all public hashes and their own receipt.
			// They still cannot replace the independently retained frozen plan.
			bad.PlanHash = bad.Plan.Hash()
			bad.EvidenceHash, _ = Digest(bad.Evidence)
			resealAlignment(&bad)
			if bad.Verify(p, d, alignmentReceipt(bad, fixtureNow)) == nil {
				t.Fatal("forged evidence/verdict accepted", name)
			}
		})
	}
	if r.Verify(p, Dataset{}, receipt) == nil {
		t.Fatal("missing dataset accepted")
	}
	if r.Verify(p, d, AlignmentReceipt{}) == nil {
		t.Fatal("missing evaluator time accepted")
	}
	wrong := receipt
	wrong.EvaluatedAt = p.RegisteredAt.Add(-time.Second)
	if r.Verify(p, d, wrong) == nil {
		t.Fatal("scoring before preregistration accepted")
	}
	d.Sources[0].Synthetic = false
	d, _ = SealDataset(d)
	if _, _, e = RunAlignment(context.Background(), d, p, relationshipGeneratorFunc(experiment.GenerateRelationshipProbe), fixtureNow); e == nil {
		t.Fatal("human ingestion authority invented")
	}
}

func TestAlignmentLabelBlindFrozenPort(t *testing.T) {
	d, p := alignmentFixture(t)
	d.Sources[0].Text = "PRIVATE_DATASET_CANARY"
	d.Cases[0].Labels[0].Annotation = "HELDOUT_LABEL_CANARY"
	d, _ = SealDataset(d)
	p.DatasetHash = d.Hash
	before, _ := json.Marshal(p)
	calls := 0
	g := relationshipGeneratorFunc(func(ctx context.Context, r experiment.RelationshipProbeRequest) (experiment.RelationshipProbe, error) {
		calls++
		raw, _ := json.Marshal(r)
		for _, secret := range []string{"PRIVATE_DATASET_CANARY", "HELDOUT_LABEL_CANARY", p.Hypothesis, p.DecisionRule, p.DatasetHash} {
			if strings.Contains(string(raw), secret) {
				t.Fatal("evaluator data/rule leaked to generator")
			}
		}
		return experiment.GenerateRelationshipProbe(ctx, r)
	})
	r, receipt, e := RunAlignment(context.Background(), d, p, g, fixtureNow)
	if e != nil || r.Verify(p, d, receipt) != nil || calls != 2 {
		t.Fatal("label-blind run", e)
	}
	after, _ := json.Marshal(p)
	if string(before) != string(after) {
		t.Fatal("frozen plan mutated")
	}
	mutating := relationshipGeneratorFunc(func(ctx context.Context, r experiment.RelationshipProbeRequest) (experiment.RelationshipProbe, error) {
		r.Seeds[0]++
		return experiment.GenerateRelationshipProbe(ctx, r)
	})
	if _, _, e = RunAlignment(context.Background(), d, p, mutating, fixtureNow); e == nil {
		t.Fatal("mutated request response binding accepted")
	}
	after, _ = json.Marshal(p)
	if string(before) != string(after) {
		t.Fatal("generator mutated retained seed slice")
	}
	bad := p
	bad.Hypothesis = "post-hoc hypothesis"
	calls = 0
	if _, _, e = RunAlignment(context.Background(), d, bad, g, fixtureNow); e == nil || calls != 0 {
		t.Fatal("unfrozen hypothesis reached generation")
	}
}

func TestAlignmentVerdictPolarity(t *testing.T) {
	d, p := alignmentFixture(t)
	first, e := experiment.GenerateRelationshipProbe(context.Background(), p.Probe)
	if e != nil {
		t.Fatal(e)
	}
	second, e := experiment.GenerateRelationshipProbe(context.Background(), p.Probe)
	if e != nil {
		t.Fatal(e)
	}
	// A well-formed repeat with a different retained state records a failed
	// engineering reproducibility experiment; it does not assert human failure.
	second.Trials[0].AfterStateHash = strings.Repeat("a", 64)
	r, e := BuildAlignmentReport(p, AlignmentEvidence{&first, &second})
	if e != nil {
		t.Fatal(e)
	}
	if r.Findings[9].Status != AlignmentFail || r.Verify(p, d, alignmentReceipt(r, fixtureNow)) != nil {
		t.Fatal("failed reproduction polarity lost")
	}
	for _, f := range r.Findings[13:] {
		if f.FalsifierTriggered != "unknown" {
			t.Fatal("engineering failure fabricated a triggered scientific falsifier")
		}
	}
	if reflect.DeepEqual(first, second) {
		t.Fatal("invalid failure fixture")
	}
}
